(()=>{
'use strict';
const V='16.2.0', LS='julih_gestao_v16_2', LEGACY_KEYS=['julih_gestao_v16_1','julih_gestao_v16','julih_gestao_v15','julih_gestao_v14','julih_gestao_v13'], CFG0=window.JULIH_CONFIG||{}; const BRL=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'});
const $=s=>document.querySelector(s), esc=(s='')=>String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); const money=v=>BRL.format(Number(v||0)); const uid=(p='ID')=>`${p}-${Date.now().toString(36).toUpperCase()}-${Math.random().toString(36).slice(2,7).toUpperCase()}`;
function localDateKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function today(){return localDateKey()}
function offsetDateKey(days){const d=new Date();d.setDate(d.getDate()+days);return localDateKey(d)}
function dateKey(v){const s=String(v||'').trim();if(!s)return'';let m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);if(m)return`${m[1]}-${m[2]}-${m[3]}`;m=s.match(/^(\d{2})\/(\d{2})\/(\d{4})/);if(m)return`${m[3]}-${m[2]}-${m[1]}`;const d=new Date(s);if(!Number.isNaN(d.getTime()))return localDateKey(d);return''}
function fmtDate(v){const k=dateKey(v);if(!k)return'—';const [y,m,d]=k.split('-');return`${d}/${m}/${y}`}
function fmtTime(v){const s=String(v||'').trim();if(!s)return'A combinar';let m=s.match(/^(\d{1,2}):(\d{2})/);if(m)return`${String(m[1]).padStart(2,'0')}:${m[2]}`;m=s.match(/T(\d{2}):(\d{2})/);if(m)return`${m[1]}:${m[2]}`;const d=new Date(s);if(!Number.isNaN(d.getTime()))return`${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;return s}
function modeText(v){const s=String(v||'').trim();if(/retir/i.test(s))return'Retirada';if(/entreg/i.test(s))return'Entrega';return s||'A combinar'}
function modeIcon(v){return /retir/i.test(String(v||''))?'🏪':/entreg/i.test(String(v||''))?'🚚':'📦'}
function normalizePhone(v){const n=String(v||'').replace(/\D/g,'');return n.startsWith('55')&&n.length>=12?n.slice(2):n}
function deliverySortKey(o){return `${dateKey(o.deliveryDate)||'9999-12-31'}T${fmtTime(o.deliveryTime)==='A combinar'?'23:59':fmtTime(o.deliveryTime)}`}
function businessDateKey(o){return dateKey(o.deliveryDate)||dateKey(o.createdAt)}
function sameWeekKey(k){if(!k)return false;const now=new Date(), d=new Date(k+'T12:00:00');const start=new Date(now);const day=(start.getDay()+6)%7;start.setDate(start.getDate()-day);start.setHours(0,0,0,0);const end=new Date(start);end.setDate(end.getDate()+7);return d>=start&&d<end}
function inFinancePeriod(k){if(!k)return false;if(view.financeStart||view.financeEnd){if(view.financeStart&&k<view.financeStart)return false;if(view.financeEnd&&k>view.financeEnd)return false;return true}if(view.financePeriod==='today')return k===today();if(view.financePeriod==='week')return sameWeekKey(k);if(view.financePeriod==='month')return k.slice(0,7)===today().slice(0,7);return true}
function statusClass(s){return `st-${esc(s||'recebido')}`}
function filterOrders(arr){const q=String(view.orderSearch||'').trim().toLowerCase();return arr.filter(o=>{const k=dateKey(o.deliveryDate),m=modeText(o.deliveryMode),f=view.orderFilter||'all';if(f==='today'&&k!==today())return false;if(f==='tomorrow'&&k!==offsetDateKey(1))return false;if(f==='pickup'&&m!=='Retirada')return false;if(f==='delivery'&&m!=='Entrega')return false;if(['recebido','producao','pronto'].includes(f)&&o.status!==f)return false;if(q){const hay=[o.id,o.customerName,o.phone,...(o.items||[]).map(i=>i.name)].join(' ').toLowerCase();if(!hay.includes(q))return false}return true}).sort((a,b)=>deliverySortKey(a).localeCompare(deliverySortKey(b)))}
function groupProduction(arr){const map=new Map();arr.forEach(o=>{const k=dateKey(o.deliveryDate)||'sem-data';if(!map.has(k))map.set(k,[]);map.get(k).push(o)});return [...map.entries()].sort((a,b)=>a[0].localeCompare(b[0]))}
function productionLabel(k){if(k==='sem-data')return'Sem data definida';if(k===today())return'Hoje · '+fmtDate(k);if(k===offsetDateKey(1))return'Amanhã · '+fmtDate(k);return fmtDate(k)}
let cfg={scriptUrl:CFG0.scriptUrl||'',adminToken:CFG0.adminToken||'',pin:'2026',storeName:'Julih & Cia',whatsapp:'',pixKey:'',deliveryFee:0}; let data={products:[],stock:[],orders:[],expenses:[],movements:[],settings:{}};let view={unlocked:false,tab:'dashboard',newOrderIds:[],entry:'intro',orderFilter:'all',orderSearch:'',financePeriod:'month',financeStart:'',financeEnd:''};let imageDraft={url:'',dataUrl:'',removed:false};
try{let raw=localStorage.getItem(LS);if(!raw){for(const k of LEGACY_KEYS){raw=localStorage.getItem(k);if(raw)break}}const x=JSON.parse(raw||'{}');cfg={...cfg,...(x.cfg||{})};view={...view,...(x.view||{}),unlocked:false};data={...data,...(x.data||{})}}catch{};
view.entry='intro';
function save(){localStorage.setItem(LS,JSON.stringify({cfg,data,view:{...view,unlocked:false}}))} function toast(msg,type=''){const h=$('#toastHost'),d=document.createElement('div');d.className='toast '+type;d.textContent=msg;h.appendChild(d);setTimeout(()=>d.remove(),3400)}; const safe=(s,f)=>{try{return JSON.parse(s)}catch{return f}};
function statusLabel(s){return ({recebido:'Recebido',confirmado:'Confirmado',producao:'Em produção',pronto:'Pronto',entregue:'Entregue',cancelado:'Cancelado'})[s]||s}
function appbar(sub='Gestão'){return `<header class="app-header"><div class="app-header-in"><div class="brand"><span class="brand-mark">J</span><div><strong>${esc(cfg.storeName||'Julih & Cia')}</strong><small>${esc(sub)}</small></div></div><div class="header-tools"><button class="install-button" data-pwa-install hidden aria-label="Instalar aplicativo"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v11m0 0 4-4m-4 4-4-4M5 20h14"/></svg><span>Instalar</span></button>${view.unlocked?'<button class="icon-button" data-action="logout" aria-label="Sair"><svg viewBox="0 0 24 24"><path d="M10 4H4v16h6M14 8l4 4-4 4M8 12h10"/></svg></button>':'<span class="status-orb">♡</span>'}</div></div></header>`}
const navItems=[['dashboard','⌂','Início'],['orders','📋','Pedidos'],['production','📅','Produção'],['products','🍰','Produtos'],['stock','📦','Estoque'],['expenses','💸','Despesas'],['finance','💰','Financeiro'],['customers','👥','Clientes'],['settings','⚙','Configurações']];
function managementIntro(){document.body.className='admin-intro-mode';$('#app').innerHTML=`<main class="admin-intro-page"><img class="intro-art" src="${window.JULIH_ART}" alt="Julih & Cia"><div class="intro-atmosphere"></div><div class="admin-intro-bottom"><div class="admin-intro-label">Área da Confeitaria</div><button class="admin-intro-cta" data-action="enter-management"><span>Acessar gestão</span><b>›</b></button><button class="intro-install" data-pwa-install hidden><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v11m0 0 4-4m-4 4-4-4M5 20h14"/></svg>Instalar aplicativo</button><small>Julih & Cia • gestão da confeitaria</small></div></main>`}
function render(){if(view.entry==='intro')return managementIntro();document.body.className='admin-watermark';if(!view.unlocked)return login();const body=({dashboard,orders,production,products,stock,expenses,finance,customers,settings})[view.tab]?.()||dashboard();const mobilePrimary=navItems.slice(0,4);$('#app').innerHTML=`<div class="watermark-art" aria-hidden="true"><img src="${window.JULIH_ART}" alt=""></div>`+appbar('Área da Confeitaria')+`<main class="shell admin-shell"><nav class="mobile-admin" aria-label="Navegação principal">${mobilePrimary.map(n=>`<button class="${view.tab===n[0]?'active':''}" data-tab="${n[0]}">${n[1]} <span>${n[2]}</span></button>`).join('')}<button data-action="mobile-more" class="${!mobilePrimary.some(n=>n[0]===view.tab)?'active':''}">☰ <span>Mais</span></button></nav><div class="admin-layout"><aside class="side">${navItems.map(n=>`<button class="${view.tab===n[0]?'active':''}" data-tab="${n[0]}">${n[1]} ${n[2]}${n[0]==='orders'&&view.newOrderIds.length?`<span class="badge-count">${view.newOrderIds.length}</span>`:''}</button>`).join('')}</aside><section class="admin-content">${banner()}${body}</section></div></main>`}
function login(){document.body.className='admin-watermark'; $('#app').innerHTML=`<div class="watermark-art" aria-hidden="true"><img src="${window.JULIH_ART}" alt=""></div>`+appbar('Gestão')+`<main class="shell"><div class="login-wrap"><div class="login-brand glass"><div class="login-mark">Julih <span>& Cia</span></div><small>Feito com amor em cada detalhe</small></div><form class="card login-card" id="loginForm"><span class="eyebrow">Área da Confeitaria</span><h1>Acesso administrativo</h1><p>Pedidos, produção, produtos, estoque, financeiro e clientes.</p><div class="field"><label>PIN</label><input class="input" type="password" name="pin" inputmode="numeric" maxlength="12" required placeholder="••••"></div><button class="btn btn-primary btn-block" style="margin-top:13px">Entrar</button><div class="note">PIN inicial: <b>2026</b>. Depois altere em Configurações.</div></form></div></main>`}
function banner(){const on=!!cfg.scriptUrl&&!!cfg.adminToken;return `<div class="banner"><div class="banner-copy"><span class="dot ${on?'on':''}"></span><span><strong>${on?'Conectado à base Google':'Configuração pendente'}</strong><small>${on?'Pedidos e catálogo sincronizados':'Informe URL e token em Configurações'}</small></span></div><button class="btn btn-soft btn-sm sync-btn" data-action="sync">↻ Sincronizar</button></div>`}
function dashboard(){const valid=data.orders.filter(o=>o.status!=='cancelado'),revenue=valid.reduce((s,o)=>s+Number(o.total||0),0),expensesV=data.expenses.reduce((s,e)=>s+Number(e.amount||0),0),result=revenue-expensesV,pending=data.orders.filter(o=>['recebido','confirmado','producao'].includes(o.status)).length,todayOrders=data.orders.filter(o=>dateKey(o.deliveryDate)===today()).sort((a,b)=>String(a.deliveryTime).localeCompare(String(b.deliveryTime))),low=data.stock.filter(s=>Number(s.qty)<=Number(s.min));return `<div class="page-title"><div><span class="eyebrow">Resumo do negócio</span><h1>Bom dia, Julih! 👋</h1><p>Acompanhe pedidos, produção e resultado em um só lugar.</p></div><button class="btn btn-primary" data-action="new-order">+ Novo pedido</button></div><div class="kpis"><div class="card metric"><span class="label">Vendas</span><div class="value">${money(revenue)}</div></div><div class="card metric"><span class="label">Despesas</span><div class="value">${money(expensesV)}</div></div><div class="card metric"><span class="label">Resultado</span><div class="value money-pos">${money(result)}</div></div><div class="card metric"><span class="label">Pedidos pendentes</span><div class="value">${pending}</div></div></div><div class="section quick-admin"><button data-action="new-order"><span>➕</span>Novo pedido</button><button data-tab="production"><span>📅</span>Produção</button><button data-tab="products"><span>🍰</span>Produtos</button><button data-action="new-expense"><span>💸</span>Despesa</button></div><div class="section charts"><div class="card"><div class="page-title" style="margin:0 0 10px"><div><h3>Pedidos de hoje</h3><p>${fmtDate(today())}</p></div><button class="btn btn-soft btn-sm" data-tab="orders">Ver todos</button></div><div class="list">${todayOrders.length?todayOrders.map(orderRow).join(''):'<div class="empty"><div class="emoji">🍰</div><h3>Nenhum pedido para hoje</h3></div>'}</div></div><div class="card"><h3 style="margin-top:0;color:var(--wine)">Estoque em atenção</h3><p style="color:var(--muted)">Itens no mínimo ou abaixo.</p><div class="list">${low.length?low.slice(0,6).map(s=>`<div class="row"><div><strong>${esc(s.name)}</strong><small>Mínimo ${s.min} ${esc(s.unit)}</small></div><div class="stock-low">${s.qty} ${esc(s.unit)}</div></div>`).join(''):'<div class="empty">✅ Estoque saudável</div>'}</div></div></div>`}
function orderRow(o){return `<button class="row" style="width:100%;text-align:left" data-order="${esc(o.id)}"><div class="row-main"><div class="avatar">${esc(o.items?.[0]?.emoji||'🎂')}</div><div><strong>${fmtTime(o.deliveryTime)} · ${esc(o.customerName)}</strong><small>${fmtDate(o.deliveryDate)} · ${modeIcon(o.deliveryMode)} ${esc(modeText(o.deliveryMode))} · ${esc(o.items?.[0]?.name||'Pedido')}</small></div></div><div class="row-right"><strong>${Number(o.total||0)>0?money(o.total):'Orçamento'}</strong><span class="status st-${esc(o.status)}">${statusLabel(o.status)}</span></div></button>`}
function orders(){view.newOrderIds=[];save();const arr=filterOrders([...data.orders]);const filters=[['all','Todos'],['today','Hoje'],['tomorrow','Amanhã'],['pickup','🏪 Retirada'],['delivery','🚚 Entrega'],['recebido','Recebidos'],['producao','Em produção'],['pronto','Prontos']];const mobile=arr.length?arr.map(o=>`<article class="order-card-mobile" data-order="${esc(o.id)}"><div class="order-card-head"><div><small>${esc(o.id)}</small><h3>${esc(o.customerName||'Cliente')}</h3></div><span class="status ${statusClass(o.status)}">${statusLabel(o.status)}</span></div><p class="order-item-name">${esc((o.items||[]).map(i=>`${i.qty}x ${i.name}`).join(', ')||'Pedido')}</p><div class="order-meta-grid"><div><span>${modeIcon(o.deliveryMode)} ${esc(modeText(o.deliveryMode))}</span><strong>${fmtDate(o.deliveryDate)}</strong><small>${fmtTime(o.deliveryTime)}</small></div><div class="order-total"><small>Total</small><strong>${Number(o.total||0)>0?money(o.total):'Orçamento'}</strong></div></div>${/entreg/i.test(modeText(o.deliveryMode))&&o.address?`<p class="order-address">📍 ${esc(o.address)}</p>`:''}<button class="btn btn-soft btn-sm" data-order="${esc(o.id)}">Abrir pedido</button></article>`).join(''):'<div class="card empty">Nenhum pedido para este filtro.</div>';return `<div class="page-title"><div><h1>Pedidos</h1><p>${arr.length} pedido(s) exibido(s) de ${data.orders.length}.</p></div><button class="btn btn-primary" data-action="new-order">+ Novo pedido</button></div><div class="order-tools card"><div class="order-search"><span>⌕</span><input class="input" id="orderSearch" value="${esc(view.orderSearch||'')}" placeholder="Buscar cliente, telefone, pedido ou produto"></div><div class="filter-chips">${filters.map(([v,l])=>`<button class="${view.orderFilter===v?'active':''}" data-order-filter="${v}">${l}</button>`).join('')}</div></div><div class="desktop-orders card"><div class="table-wrap"><table class="table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Entrega / Retirada</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>${arr.length?arr.map(o=>`<tr><td><strong>${esc(o.id)}</strong><br><small>${esc(o.items?.[0]?.name||'Pedido')}</small></td><td>${esc(o.customerName)}<br><small>${esc(o.phone||'')}</small></td><td><span class="mode-badge mode-${/retir/i.test(String(o.deliveryMode||''))?'pickup':'delivery'}">${modeIcon(o.deliveryMode)} ${esc(modeText(o.deliveryMode))}</span><br><strong>${fmtDate(o.deliveryDate)}</strong><br><small>${fmtTime(o.deliveryTime)}</small></td><td>${Number(o.total||0)>0?money(o.total):'Orçamento'}</td><td><span class="status ${statusClass(o.status)}">${statusLabel(o.status)}</span></td><td><button class="btn btn-soft btn-sm" data-order="${esc(o.id)}">Abrir</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">Nenhum pedido.</td></tr>'}</tbody></table></div></div><div class="mobile-orders">${mobile}</div>`}
function production(){const arr=data.orders.filter(o=>['confirmado','producao','pronto'].includes(o.status)).sort((a,b)=>deliverySortKey(a).localeCompare(deliverySortKey(b)));const groups=groupProduction(arr);return `<div class="page-title"><div><h1>Agenda de produção</h1><p>Organizada pela data e horário prometidos ao cliente.</p></div></div><div class="production-groups">${groups.length?groups.map(([k,orders])=>`<section class="production-day"><div class="production-day-title"><h3>${productionLabel(k)}</h3><span>${orders.length} pedido(s)</span></div>${orders.map(o=>`<button class="production-card" data-order="${esc(o.id)}"><div><strong>${fmtTime(o.deliveryTime)} · ${esc(o.customerName)}</strong><small>${modeIcon(o.deliveryMode)} ${esc(modeText(o.deliveryMode))} · ${esc((o.items||[]).map(i=>`${i.qty}x ${i.name}`).join(', '))}</small></div><span class="status ${statusClass(o.status)}">${statusLabel(o.status)}</span></button>`).join('')}</section>`).join(''):'<div class="card empty">📅 Nenhum pedido em produção.</div>'}</div>`}
function products(){return `<div class="page-title"><div><span class="eyebrow">Catálogo conectado</span><h1>Produtos</h1><p>Fotos, preços e pronta entrega atualizam o aplicativo dos clientes.</p></div><button class="btn btn-primary" data-action="new-product">+ Novo produto</button></div><div class="product-grid admin">${data.products.length?data.products.map(p=>{const ready=String(p.readyStockEnabled)==='true'||p.readyStockEnabled===true;return `<article class="product"><div class="visual">${p.imageUrl?`<img src="${esc(p.imageUrl)}" alt="${esc(p.name)}">`:`<span>${esc(p.emoji||'🍰')}</span>`}${ready?`<span class="ready-badge ${Number(p.readyStock)<=0?'out':''}">${Number(p.readyStock)<=0?'Esgotado':`${Number(p.readyStock)} disponíveis`}</span>`:''}</div><div class="content"><div><span class="badge">${esc(p.category)}</span> <span class="badge">${p.active!==false?'Ativo':'Inativo'}</span></div><h3>${esc(p.name)}</h3><p>${esc(p.description||'')}</p><span class="price">${Number(p.price)>0?money(p.price):'Orçamento'}</span><div class="product-actions"><button class="btn btn-soft btn-sm" data-edit-product="${esc(p.id)}">✎ Editar</button></div></div></article>`}).join(''):'<div class="card empty" style="grid-column:1/-1">Nenhum produto cadastrado.</div>'}</div>`}
function stock(){const history=[...(data.movements||[])].sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt))).slice(0,12);return `<div class="page-title"><div><h1>Estoque</h1><p>Ingredientes, embalagens e materiais com histórico de movimentações.</p></div><button class="btn btn-primary" data-action="new-stock">+ Novo item</button></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Item</th><th>Saldo</th><th>Mínimo</th><th>Custo</th><th>Situação</th><th></th></tr></thead><tbody>${data.stock.length?data.stock.map(s=>`<tr><td><strong>${esc(s.name)}</strong><br><small>${esc(s.unit)}</small></td><td>${s.qty} ${esc(s.unit)}</td><td>${s.min} ${esc(s.unit)}</td><td>${money(s.cost)}</td><td>${Number(s.qty)<=Number(s.min)?'<span class="stock-low">⚠ Baixo</span>':'<span class="stock-ok">✓ OK</span>'}</td><td><button class="btn btn-soft btn-sm" data-stock="${esc(s.id)}">Ajustar</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">Nenhum item de estoque.</td></tr>'}</tbody></table></div></div><div class="card section"><div class="section-head"><div><h3>Últimas movimentações</h3><p>Entradas, saídas e correções registradas.</p></div></div><div class="movement-list">${history.length?history.map(m=>`<div class="movement-row"><div><strong>${esc(m.itemName||'Item')}</strong><small>${fmtDate(m.createdAt)} · ${new Date(m.createdAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})} · ${esc(m.reason||'Sem motivo informado')}</small></div><div class="movement-value ${/remove|sa[ií]da/i.test(String(m.operation||''))?'out':'in'}">${/remove|sa[ií]da/i.test(String(m.operation||''))?'-':/add|entrada/i.test(String(m.operation||''))?'+':'='}${Number(m.quantity||0)}<small>${Number(m.previousQty||0)} → ${Number(m.newQty||0)}</small></div></div>`).join(''):'<div class="empty">Nenhuma movimentação registrada ainda.</div>'}</div></div>`}
function expenses(){const arr=[...data.expenses].sort((a,b)=>String(b.date).localeCompare(String(a.date)));return `<div class="page-title"><div><h1>Despesas</h1><p>Compras e gastos da confeitaria.</p></div><button class="btn btn-primary" data-action="new-expense">+ Nova despesa</button></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Categoria</th><th>Descrição</th><th>Valor</th></tr></thead><tbody>${arr.length?arr.map(e=>`<tr><td>${fmtDate(e.date)}</td><td>${esc(e.category)}</td><td>${esc(e.description)}</td><td class="money-neg">-${money(e.amount)}</td></tr>`).join(''):'<tr><td colspan="4" class="empty">Nenhuma despesa.</td></tr>'}</tbody></table></div></div>`}
function finance(){const valid=data.orders.filter(o=>o.status!=='cancelado'&&inFinancePeriod(businessDateKey(o))),expList=data.expenses.filter(e=>inFinancePeriod(dateKey(e.date))),rev=valid.reduce((s,o)=>s+Number(o.total||0),0),exp=expList.reduce((s,e)=>s+Number(e.amount||0),0),paid=valid.reduce((s,o)=>s+Number(o.paid||0),0),receivable=Math.max(0,rev-paid),res=rev-exp,max=Math.max(rev,exp,1);const periods=[['today','Hoje'],['week','Esta semana'],['month','Este mês'],['all','Tudo']];return `<div class="page-title"><div><h1>Financeiro</h1><p>Entradas, despesas e valores a receber por período.</p></div></div><div class="finance-filters card"><div class="filter-chips">${periods.map(([v,l])=>`<button class="${view.financePeriod===v&&!view.financeStart&&!view.financeEnd?'active':''}" data-finance-period="${v}">${l}</button>`).join('')}</div><div class="date-range"><label>De <input class="input" id="financeStart" type="date" value="${esc(view.financeStart||'')}"></label><label>Até <input class="input" id="financeEnd" type="date" value="${esc(view.financeEnd||'')}"></label><button class="btn btn-soft btn-sm" data-action="finance-clear">Limpar período</button></div></div><div class="kpis"><div class="card metric"><span class="label">Vendas</span><div class="value">${money(rev)}</div></div><div class="card metric"><span class="label">Recebido</span><div class="value">${money(paid)}</div></div><div class="card metric"><span class="label">A receber</span><div class="value">${money(receivable)}</div></div><div class="card metric"><span class="label">Resultado</span><div class="value ${res<0?'money-neg':'money-pos'}">${money(res)}</div></div></div><div class="section charts"><div class="card"><h3 style="color:var(--wine);margin-top:0">Vendas x despesas</h3><p>Vendas <span style="float:right">${money(rev)}</span></p><div class="barline"><span style="width:${rev/max*100}%"></span></div><p>Despesas <span style="float:right">${money(exp)}</span></p><div class="barline"><span style="width:${exp/max*100}%"></span></div></div><div class="card"><h3 style="color:var(--wine);margin-top:0">Indicadores</h3><div class="row"><span>Ticket médio</span><strong>${money(valid.length?rev/valid.length:0)}</strong></div><div class="row"><span>Pedidos válidos</span><strong>${valid.length}</strong></div><div class="row"><span>Despesas</span><strong>${expList.length}</strong></div><div class="row"><span>Margem após despesas</span><strong>${rev?((res/rev)*100).toFixed(1):0}%</strong></div></div></div>`}
function customers(){const m=new Map();data.orders.filter(o=>o.status!=='cancelado').forEach(o=>{const phone=normalizePhone(o.phone),name=String(o.customerName||'').trim().toLowerCase(),k=phone||name;if(!k)return;const x=m.get(k)||{name:o.customerName,phone:o.phone,count:0,total:0,last:''};x.count++;x.total+=Number(o.total||0);if(String(o.createdAt)>x.last)x.last=o.createdAt;m.set(k,x)});const arr=[...m.values()].sort((a,b)=>b.total-a.total);return `<div class="page-title"><div><h1>Clientes</h1><p>Telefones normalizados para evitar clientes duplicados.</p></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Cliente</th><th>WhatsApp</th><th>Pedidos</th><th>Total comprado</th><th>Último pedido</th></tr></thead><tbody>${arr.length?arr.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(c.phone||'')}</td><td>${c.count}</td><td>${money(c.total)}</td><td>${c.last?new Date(c.last).toLocaleDateString('pt-BR'):'—'}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">Nenhum cliente ainda.</td></tr>'}</tbody></table></div></div>`}
function settings(){const notif=('Notification'in window)?Notification.permission:'indisponível';return `<div class="page-title"><div><h1>Configurações</h1><p>Conexão, segurança e notificações.</p></div></div><form class="card" id="settingsForm"><div class="form-grid"><div class="field full"><label>URL do Google Apps Script</label><input class="input" name="scriptUrl" value="${esc(cfg.scriptUrl)}" placeholder="https://script.google.com/macros/s/.../exec"><small>Use a URL terminada em /exec.</small></div><div class="field full"><label>Token administrativo</label><input class="input" name="adminToken" value="${esc(cfg.adminToken)}" placeholder="Copie da aba Config da planilha"></div><div class="field"><label>PIN deste aparelho</label><input class="input" name="pin" value="${esc(cfg.pin)}" inputmode="numeric"></div><div class="field"><label>Nome exibido</label><input class="input" name="storeName" value="${esc(cfg.storeName)}"></div><div class="field"><label>WhatsApp público</label><input class="input" name="whatsapp" value="${esc(cfg.whatsapp)}"></div><div class="field"><label>Chave Pix pública</label><input class="input" name="pixKey" value="${esc(cfg.pixKey)}"></div><div class="field"><label>Taxa de entrega padrão</label><input class="input" name="deliveryFee" type="number" min="0" step="0.01" value="${Number(cfg.deliveryFee||0)}"></div></div><div class="form-actions"><button type="button" class="btn btn-soft" data-action="test">Testar conexão</button><button class="btn btn-primary">Salvar</button></div></form><div class="card section notification-card"><div><h3>Notificações de novos pedidos</h3><p>Status atual: <b>${esc(notif)}</b>. Ative para receber um aviso quando a Gestão estiver em uso.</p></div><button class="btn btn-soft" data-action="notifications">Ativar notificações</button></div>`}
function modal(title,body){const d=document.createElement('div');d.className='modal-bg';d.innerHTML=`<div class="modal"><div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close">✕</button></div><div class="modal-body">${body}</div></div>`;document.body.appendChild(d)} function close(){document.querySelector('.modal-bg')?.remove()}
async function api(action,d={},admin=true){if(!cfg.scriptUrl)throw new Error('URL do Apps Script não configurada.');const payload={action,data:d};if(admin)payload.adminToken=cfg.adminToken;const r=await fetch(cfg.scriptUrl,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(payload)});const j=await r.json();if(j.ok===false)throw new Error(j.error||'Erro no Apps Script');return j}
function adminReady(){if(!cfg.scriptUrl)throw new Error('URL do Apps Script não configurada. Abra Configurações.');if(!cfg.adminToken)throw new Error('Token administrativo não configurado. Abra Configurações e cole o adminToken da aba Config.');}
function setFormBusy(form,busy,label='Salvando...'){const btn=form?.querySelector('button[type="submit"], .form-actions .btn-primary');if(!btn)return;if(busy){btn.dataset.originalText=btn.textContent;btn.disabled=true;btn.textContent=label}else{btn.disabled=false;btn.textContent=btn.dataset.originalText||'Salvar';delete btn.dataset.originalText}}
function normalize(){data.products=(data.products||[]).map(p=>({...p,price:Number(p.price||0),readyStock:Number(p.readyStock||0),active:String(p.active)!=='false',readyStockEnabled:String(p.readyStockEnabled)==='true'||p.readyStockEnabled===true,featured:String(p.featured)==='true'||p.featured===true}));data.stock=(data.stock||[]).map(s=>({...s,qty:Number(s.qty||0),min:Number(s.min||0),cost:Number(s.cost||0)}));data.orders=(data.orders||[]).map(o=>({...o,total:Number(o.total||0),paid:Number(o.paid||0),items:typeof o.items==='string'?safe(o.items,[]):o.items||[]}));data.expenses=(data.expenses||[]).map(e=>({...e,amount:Number(e.amount||0)}));data.movements=(data.movements||[]).map(m=>({...m,quantity:Number(m.quantity||0),previousQty:Number(m.previousQty||0),newQty:Number(m.newQty||0)}))}
async function sync(silent=false){if(!cfg.scriptUrl||!cfg.adminToken){if(!silent)toast('Configure URL e token.','error');return}try{const old=new Set(data.orders.map(o=>String(o.id)));const d=await api('adminBootstrap');data={products:d.products||[],stock:d.stock||[],orders:d.orders||[],expenses:d.expenses||[],movements:d.stockMovements||[],settings:d.settings||{}};normalize();const fresh=data.orders.filter(o=>!old.has(String(o.id))).map(o=>o.id);if(old.size&&fresh.length){view.newOrderIds=[...new Set([...view.newOrderIds,...fresh])];toast(`${fresh.length} novo(s) pedido(s) recebido(s)!`,'success');if('Notification'in window&&Notification.permission==='granted')new Notification('Julih & Cia',{body:`${fresh.length} novo(s) pedido(s).`})}cfg.storeName=data.settings.storeName||cfg.storeName;cfg.whatsapp=data.settings.whatsapp||cfg.whatsapp;cfg.pixKey=data.settings.pixKey||cfg.pixKey;cfg.deliveryFee=Number(data.settings.deliveryFee||cfg.deliveryFee||0);save();render();if(!silent)toast('Dados sincronizados.','success')}catch(e){if(!silent)toast(e.message,'error')} }
function editProduct(id){const p=id?data.products.find(x=>String(x.id)===String(id)):null;imageDraft={url:p?.imageUrl||'',dataUrl:'',removed:false};modal(p?'Editar produto':'Novo produto',`<form id="productForm"><input type="hidden" name="id" value="${esc(p?.id||'')}"><div class="product-editor"><div><div class="field"><label>Imagem do produto</label></div><div class="photo-preview" id="photoPreview"></div><div class="photo-actions"><label class="btn btn-soft btn-sm">🖼️ Galeria<input id="galleryInput" hidden type="file" accept="image/*"></label><label class="btn btn-soft btn-sm">📷 Câmera<input id="cameraInput" hidden type="file" accept="image/*" capture="environment"></label><button type="button" class="btn btn-danger btn-sm" data-action="remove-photo">Remover</button></div><div class="note">A imagem é reduzida e enviada para o Google Drive.</div></div><div class="form-grid"><div class="field full"><label>Nome</label><input class="input" name="name" value="${esc(p?.name||'')}" required></div><div class="field"><label>Categoria</label><select class="select" name="category">${['Bolos','Doces','Kits','Pronta entrega','Personalizados'].map(c=>`<option ${p?.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Ícone</label><input class="input" name="emoji" value="${esc(p?.emoji||'🍰')}" maxlength="4"></div><div class="field"><label>Preço</label><input class="input" name="price" type="number" min="0" step="0.01" value="${Number(p?.price||0)}"></div><div class="field"><label>Ativo</label><select class="select" name="active"><option value="true" ${p?.active!==false?'selected':''}>Sim</option><option value="false" ${p?.active===false?'selected':''}>Não</option></select></div><div class="field"><label>Pronta entrega?</label><select class="select" name="readyStockEnabled"><option value="false" ${!(p?.readyStockEnabled===true||String(p?.readyStockEnabled)==='true')?'selected':''}>Não</option><option value="true" ${(p?.readyStockEnabled===true||String(p?.readyStockEnabled)==='true')?'selected':''}>Sim</option></select></div><div class="field"><label>Quantidade disponível</label><input class="input" name="readyStock" type="number" min="0" step="1" value="${Number(p?.readyStock||0)}"></div><div class="field"><label>Destaque no catálogo</label><select class="select" name="featured"><option value="false" ${!(p?.featured===true||String(p?.featured)==='true')?'selected':''}>Não</option><option value="true" ${(p?.featured===true||String(p?.featured)==='true')?'selected':''}>Sim</option></select></div><div class="field full"><label>Descrição</label><textarea class="textarea" name="description">${esc(p?.description||'')}</textarea></div></div></div><div class="form-actions"><button type="button" class="btn btn-soft" data-action="close">Cancelar</button><button type="submit" class="btn btn-primary">Salvar produto</button></div></form>`);requestAnimationFrame(updatePreview)}
function updatePreview(){const b=$('#photoPreview');if(!b)return;const src=imageDraft.removed?'':(imageDraft.dataUrl||imageDraft.url||'');b.innerHTML=src?`<img src="${esc(src)}" alt="Prévia">`:'<div>📷<br><b>Foto do produto</b><br><small>Galeria ou câmera</small></div>'}
function resize(file,max=1200,q=.84){return new Promise((res,rej)=>{if(!file||!file.type.startsWith('image/'))return rej(new Error('Selecione uma imagem.'));const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const s=Math.min(1,max/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*s);c.height=Math.round(im.height*s);c.getContext('2d').drawImage(im,0,0,c.width,c.height);res(c.toDataURL('image/jpeg',q))};im.onerror=()=>rej(new Error('Imagem inválida.'));im.src=r.result};r.onerror=()=>rej(new Error('Falha ao ler imagem.'));r.readAsDataURL(file)})}
function orderDetail(id){const o=data.orders.find(x=>String(x.id)===String(id));if(!o)return;const modalidade=modeText(o.deliveryMode);const itemFields=(o.items||[]).map((i,idx)=>`<div class="item-edit"><input type="hidden" name="item_${idx}_productId" value="${esc(i.productId||'')}"><div class="field full"><label>Item ${idx+1}</label><input class="input" name="item_${idx}_name" value="${esc(i.name||'')}" required></div><div class="field"><label>Quantidade</label><input class="input" name="item_${idx}_qty" type="number" min="1" step="1" value="${Number(i.qty||1)}"></div><div class="field"><label>Preço unitário</label><input class="input" name="item_${idx}_price" type="number" min="0" step="0.01" value="${Number(i.price||0)}"></div></div>`).join('');modal(`Pedido ${esc(o.id)}`,`<form id="orderForm"><input type="hidden" name="id" value="${esc(o.id)}"><input type="hidden" name="itemCount" value="${(o.items||[]).length}"><div class="form-grid"><div class="field"><label>Cliente</label><input class="input" name="customerName" value="${esc(o.customerName||'')}" required></div><div class="field"><label>WhatsApp</label><input class="input" name="phone" value="${esc(o.phone||'')}"></div><div class="field"><label>Data</label><input class="input" name="deliveryDate" type="date" value="${esc(dateKey(o.deliveryDate))}" required></div><div class="field"><label>Horário</label><input class="input" name="deliveryTime" type="time" value="${esc(fmtTime(o.deliveryTime)==='A combinar'?'':fmtTime(o.deliveryTime))}"></div><div class="field"><label>Modalidade</label><select class="select" name="deliveryMode"><option ${modalidade==='Retirada'?'selected':''}>Retirada</option><option ${modalidade==='Entrega'?'selected':''}>Entrega</option></select></div><div class="field address-field ${modalidade==='Entrega'?'':'hidden'}"><label>Endereço de entrega</label><input class="input" name="address" value="${esc(o.address||'')}"></div><div class="field"><label>Status</label><select class="select" name="status">${['recebido','confirmado','producao','pronto','entregue','cancelado'].map(s=>`<option value="${s}" ${o.status===s?'selected':''}>${statusLabel(s)}</option>`).join('')}</select></div><div class="field"><label>Pagamento</label><select class="select" name="paymentMethod">${['Pix','Dinheiro','Débito','Crédito','A combinar'].map(p=>`<option ${o.paymentMethod===p?'selected':''}>${p}</option>`).join('')}</select></div><div class="field"><label>Valor total</label><input class="input" name="total" type="number" min="0" step="0.01" value="${Number(o.total||0)}"></div><div class="field"><label>Valor recebido</label><input class="input" name="paid" type="number" min="0" step="0.01" value="${Number(o.paid||0)}"></div><div class="field full"><label>Observações do pedido</label><textarea class="textarea" name="notes">${esc(o.notes||'')}</textarea></div><div class="field full"><label>Observações internas</label><textarea class="textarea" name="internalNotes">${esc(o.internalNotes||'')}</textarea></div></div><div class="item-edit-list"><h3>Itens do pedido</h3>${itemFields||'<p>Nenhum item.</p>'}</div><div class="form-actions sticky-actions"><button type="button" class="btn btn-soft" data-action="whatsapp-order" data-id="${esc(o.id)}">WhatsApp</button><button class="btn btn-primary">Salvar alterações</button></div></form>`);requestAnimationFrame(()=>toggleAddressField(document.querySelector('#orderForm')))}
function manualProductOptions(){const active=(data.products||[]).filter(p=>p.active!==false);return active.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}${Number(p.price)>0?` — ${money(p.price)}`:' — Orçamento'}</option>`).join('')}
function newOrder(){modal('Novo pedido manual',`<form id="newOrderForm"><div class="form-grid"><div class="field"><label>Cliente</label><input class="input" name="customerName" required></div><div class="field"><label>WhatsApp</label><input class="input" name="phone"></div><div class="field full"><label>Produto</label><select class="select" name="productId" required><option value="">Selecione um produto...</option>${manualProductOptions()}<option value="__CUSTOM__">Outro / item personalizado</option></select></div><div class="field full manual-custom-field hidden"><label>Descrição do item personalizado</label><input class="input" name="customItemName" placeholder="Ex.: Bolo 2 kg tema aniversário"></div><div class="field"><label>Quantidade</label><input class="input" name="qty" type="number" min="1" step="1" value="1" required></div><div class="field"><label>Valor total</label><input class="input" name="total" type="number" min="0" step="0.01" required></div><div class="field"><label>Valor recebido</label><input class="input" name="paid" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Data</label><input class="input" name="deliveryDate" type="date" min="${today()}" value="${today()}" required></div><div class="field"><label>Horário</label><input class="input" name="deliveryTime" type="time" required></div><div class="field"><label>Modalidade</label><select class="select" name="deliveryMode"><option>Retirada</option><option>Entrega</option></select></div><div class="field address-field hidden"><label>Endereço de entrega</label><input class="input" name="address" placeholder="Rua, número, bairro e referência"></div><div class="field"><label>Pagamento</label><select class="select" name="paymentMethod"><option>Pix</option><option>Dinheiro</option><option>Débito</option><option>Crédito</option><option>A combinar</option></select></div><div class="field full"><label>Observações</label><textarea class="textarea" name="notes" placeholder="Sabor, recheio, tema, mensagem, detalhes do pedido..."></textarea></div></div><div class="form-actions"><button type="button" class="btn btn-soft" data-action="close">Cancelar</button><button class="btn btn-primary">Salvar</button></div></form>`);requestAnimationFrame(()=>{const f=document.querySelector('#newOrderForm');toggleAddressField(f);updateManualOrderProduct(f)})}
function updateManualOrderProduct(form){if(!form)return;const sel=form.querySelector('[name="productId"]'),qty=form.querySelector('[name="qty"]'),total=form.querySelector('[name="total"]'),customWrap=form.querySelector('.manual-custom-field'),custom=form.querySelector('[name="customItemName"]');if(!sel)return;const isCustom=sel.value==='__CUSTOM__';customWrap?.classList.toggle('hidden',!isCustom);if(custom)custom.required=isCustom;const p=(data.products||[]).find(x=>String(x.id)===String(sel.value));if(p&&total){const q=Math.max(1,Number(qty?.value||1));total.value=(Number(p.price||0)*q).toFixed(2)}else if(!sel.value&&total)total.value=''}
function toggleAddressField(form){if(!form)return;const mode=form.querySelector('[name="deliveryMode"]'),wrap=form.querySelector('.address-field'),input=form.querySelector('[name="address"]');if(!mode||!wrap||!input)return;const delivery=/entreg/i.test(mode.value);wrap.classList.toggle('hidden',!delivery);input.required=delivery}
function newExpense(){modal('Nova despesa',`<form id="expenseForm"><div class="form-grid"><div class="field"><label>Data</label><input class="input" name="date" type="date" value="${today()}" required></div><div class="field"><label>Categoria</label><select class="select" name="category"><option>Ingredientes</option><option>Embalagens</option><option>Energia</option><option>Água</option><option>Gás</option><option>Entrega</option><option>Marketing</option><option>Equipamentos</option><option>Outros</option></select></div><div class="field full"><label>Descrição</label><input class="input" name="description" required></div><div class="field"><label>Valor</label><input class="input" name="amount" type="number" min="0" step="0.01" required></div><div class="field"><label>Pagamento</label><select class="select" name="paymentMethod"><option>Pix</option><option>Dinheiro</option><option>Débito</option><option>Crédito</option><option>Boleto</option></select></div></div><div class="form-actions"><button type="button" class="btn btn-soft" data-action="close">Cancelar</button><button class="btn btn-primary">Salvar</button></div></form>`)}
function newStock(){modal('Novo item de estoque',`<form id="newStockForm"><div class="form-grid"><div class="field full"><label>Item</label><input class="input" name="name" required></div><div class="field"><label>Unidade</label><select class="select" name="unit"><option>un</option><option>kg</option><option>g</option><option>L</option><option>ml</option><option>cx</option><option>pct</option></select></div><div class="field"><label>Saldo</label><input class="input" name="qty" type="number" step="0.001" value="0"></div><div class="field"><label>Mínimo</label><input class="input" name="min" type="number" step="0.001" value="0"></div><div class="field"><label>Custo</label><input class="input" name="cost" type="number" step="0.01" value="0"></div></div><div class="form-actions"><button type="button" class="btn btn-soft" data-action="close">Cancelar</button><button class="btn btn-primary">Salvar</button></div></form>`)}
function adjustStock(id){const s=data.stock.find(x=>String(x.id)===String(id));if(!s)return;modal(`Ajustar ${esc(s.name)}`,`<form id="stockForm"><input type="hidden" name="id" value="${esc(s.id)}"><div class="form-grid"><div class="field"><label>Operação</label><select class="select" name="operation"><option value="add">Entrada (+)</option><option value="remove">Saída (-)</option><option value="set">Definir saldo</option></select></div><div class="field"><label>Quantidade</label><input class="input" name="qty" type="number" min="0" step="0.001" required></div><div class="field full"><label>Motivo</label><input class="input" name="reason"></div></div><div class="form-actions"><button type="button" class="btn btn-soft" data-action="close">Cancelar</button><button class="btn btn-primary">Aplicar</button></div></form>`)}
document.addEventListener('click',e=>{const t=e.target.closest('[data-action],[data-tab],[data-order],[data-edit-product],[data-stock],[data-order-filter],[data-finance-period]');if(!t)return;if(t.dataset.tab){view.tab=t.dataset.tab;save();close();render();return}if(t.dataset.orderFilter){view.orderFilter=t.dataset.orderFilter;save();render();return}if(t.dataset.financePeriod){view.financePeriod=t.dataset.financePeriod;view.financeStart='';view.financeEnd='';save();render();return}if(t.dataset.order){orderDetail(t.dataset.order);return}if(t.dataset.editProduct){editProduct(t.dataset.editProduct);return}if(t.dataset.stock){adjustStock(t.dataset.stock);return}switch(t.dataset.action){case'enter-management':view.entry='login';save();render();break;case'logout':view.unlocked=false;view.entry='intro';save();render();break;case'sync':sync();break;case'close':close();break;case'mobile-more':mobileMenu();break;case'new-product':editProduct();break;case'new-order':newOrder();break;case'new-expense':newExpense();break;case'new-stock':newStock();break;case'finance-clear':view.financeStart='';view.financeEnd='';view.financePeriod='month';save();render();break;case'notifications':requestNotifications();break;case'remove-photo':imageDraft={url:'',dataUrl:'',removed:true};updatePreview();break;case'test':api('adminBootstrap').then(()=>toast('Conexão funcionando.','success')).catch(x=>toast(x.message,'error'));break;case'whatsapp-order':{const o=data.orders.find(x=>String(x.id)===String(t.dataset.id));if(!o)return;const n=String(o.phone||'').replace(/\D/g,'');if(n)window.open(`https://wa.me/${n}?text=${encodeURIComponent(`Olá, ${o.customerName}! Sobre seu pedido ${o.id}: ${statusLabel(o.status)}.`)}`,'_blank');break}}});
function mobileMenu(){modal('Mais opções',`<div class="mobile-menu-grid">${navItems.map(n=>`<button class="${view.tab===n[0]?'active':''}" data-tab="${n[0]}"><span>${n[1]}</span>${n[2]}</button>`).join('')}</div>`)}
async function requestNotifications(){if(!('Notification'in window))return toast('Notificações não são suportadas neste navegador.','error');try{const p=await Notification.requestPermission();toast(p==='granted'?'Notificações ativadas.':'Permissão não concedida.',p==='granted'?'success':'error');render()}catch(e){toast('Não foi possível ativar notificações.','error')}}
document.addEventListener('change',async e=>{if(e.target.id==='galleryInput'||e.target.id==='cameraInput'){try{imageDraft.dataUrl=await resize(e.target.files?.[0]);imageDraft.removed=false;updatePreview()}catch(x){toast(x.message,'error')}}if(e.target.name==='deliveryMode')toggleAddressField(e.target.form);if(e.target.name==='productId'||(e.target.name==='qty'&&e.target.form?.id==='newOrderForm'))updateManualOrderProduct(e.target.form);if(e.target.id==='financeStart'||e.target.id==='financeEnd'){view.financeStart=$('#financeStart')?.value||'';view.financeEnd=$('#financeEnd')?.value||'';save();render()}});
document.addEventListener('input',e=>{if(e.target.id==='orderSearch'){view.orderSearch=e.target.value;clearTimeout(window.__orderSearchTimer);window.__orderSearchTimer=setTimeout(()=>{save();render();requestAnimationFrame(()=>{const q=$('#orderSearch');if(q){q.focus();q.setSelectionRange(q.value.length,q.value.length)}})},180)}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,fd=Object.fromEntries(new FormData(f).entries());if(f.id==='loginForm'){if(fd.pin===cfg.pin){view.unlocked=true;view.entry='app';save();render();sync(true)}else toast('PIN incorreto.','error');return}if(f.id==='settingsForm'){cfg={...cfg,scriptUrl:fd.scriptUrl.trim(),adminToken:fd.adminToken.trim(),pin:fd.pin.trim()||'2026',storeName:fd.storeName.trim()||'Julih & Cia',whatsapp:fd.whatsapp.trim(),pixKey:fd.pixKey.trim(),deliveryFee:Number(fd.deliveryFee||0)};save();try{if(cfg.scriptUrl&&cfg.adminToken)await api('updatePublicSettings',{storeName:cfg.storeName,whatsapp:cfg.whatsapp,pixKey:cfg.pixKey,deliveryFee:cfg.deliveryFee});toast('Configurações salvas.','success');sync(true)}catch(x){toast('Salvo neste aparelho. '+x.message,'error')}render();return}if(f.id==='productForm'){try{adminReady()}catch(x){toast(x.message,'error');return}const productId=fd.id||uid('P');let imageUrl=imageDraft.removed?'':imageDraft.url;const rec={id:productId,name:String(fd.name||'').trim(),category:fd.category,price:Number(fd.price||0),emoji:fd.emoji||'🍰',active:fd.active==='true',description:fd.description||'',imageUrl,readyStockEnabled:fd.readyStockEnabled==='true',readyStock:Number(fd.readyStock||0),featured:fd.featured==='true'};if(!rec.name){toast('Informe o nome do produto.','error');return}setFormBusy(f,true,'Salvando produto...');try{const saved=await api('upsertProduct',rec);let finalProduct=saved.product||rec;let photoWarning='';if(imageDraft.dataUrl){setFormBusy(f,true,'Enviando foto...');try{const up=await api('uploadProductImage',{dataUrl:imageDraft.dataUrl,productId,productName:rec.name});if(up.imageUrl){imageUrl=up.imageUrl;const withPhoto={...rec,imageUrl};const savedPhoto=await api('upsertProduct',withPhoto);finalProduct=savedPhoto.product||withPhoto}}catch(imgErr){photoWarning=' A foto não foi enviada, mas o produto foi salvo.';console.warn('Falha no upload da foto:',imgErr)}}const idx=data.products.findIndex(x=>String(x.id)===String(productId));if(idx>=0)data.products[idx]={...data.products[idx],...finalProduct};else data.products.push(finalProduct);normalize();save();close();render();toast('Produto salvo na planilha e publicado no catálogo.'+photoWarning,photoWarning?'':'success');sync(true)}catch(x){setFormBusy(f,false);toast('Não foi possível salvar o produto: '+x.message,'error')}return}if(f.id==='orderForm'){const o=data.orders.find(x=>String(x.id)===String(fd.id));if(!o)return;const count=Number(fd.itemCount||0),items=[];for(let i=0;i<count;i++)items.push({productId:fd[`item_${i}_productId`]||o.items?.[i]?.productId||'',name:fd[`item_${i}_name`]||'',qty:Number(fd[`item_${i}_qty`]||1),price:Number(fd[`item_${i}_price`]||0),emoji:o.items?.[i]?.emoji||'🎂',notes:o.items?.[i]?.notes||''});const rec={...o,customerName:fd.customerName,phone:fd.phone||'',deliveryDate:fd.deliveryDate,deliveryTime:fd.deliveryTime,deliveryMode:fd.deliveryMode,address:/entreg/i.test(fd.deliveryMode)?(fd.address||''):'',status:fd.status,paymentMethod:fd.paymentMethod,total:Number(fd.total||0),paid:Number(fd.paid||0),notes:fd.notes||'',internalNotes:fd.internalNotes||'',items};try{await api('updateOrder',rec);close();toast('Pedido atualizado. O cliente verá as alterações.','success');sync(true)}catch(x){toast(x.message,'error')}return}if(f.id==='newOrderForm'){const p=(data.products||[]).find(x=>String(x.id)===String(fd.productId));const isCustom=fd.productId==='__CUSTOM__';const itemName=isCustom?String(fd.customItemName||'').trim():String(p?.name||'').trim();if(!itemName)return toast('Selecione o produto ou informe a descrição do item.','error');const qty=Math.max(1,Number(fd.qty||1));const unitPrice=p&&Number(p.price)>0?Number(p.price):Number(fd.total||0)/qty;const rec={id:uid('JC'),createdAt:new Date().toISOString(),customerName:fd.customerName,phone:fd.phone||'',items:[{productId:p?.id||'MANUAL',name:itemName,emoji:p?.emoji||'🎂',price:unitPrice,qty,notes:fd.notes||''}],deliveryDate:fd.deliveryDate,deliveryTime:fd.deliveryTime,deliveryMode:fd.deliveryMode,address:/entreg/i.test(fd.deliveryMode)?(fd.address||''):'',notes:fd.notes||'',paymentMethod:fd.paymentMethod,total:Number(fd.total||0),paid:Number(fd.paid||0),status:'confirmado',internalNotes:''};try{await api('createOrder',rec,false);close();toast('Pedido criado.','success');sync(true)}catch(x){toast(x.message,'error')}return}if(f.id==='expenseForm'){const rec={id:uid('E'),date:fd.date,category:fd.category,description:fd.description,amount:Number(fd.amount||0),paymentMethod:fd.paymentMethod,createdAt:new Date().toISOString()};try{await api('createExpense',rec);close();toast('Despesa registrada.','success');sync(true)}catch(x){toast(x.message,'error')}return}if(f.id==='newStockForm'){const rec={id:uid('S'),name:fd.name,unit:fd.unit,qty:Number(fd.qty||0),min:Number(fd.min||0),cost:Number(fd.cost||0)};try{await api('upsertStock',rec);close();toast('Item de estoque criado.','success');sync(true)}catch(x){toast(x.message,'error')}return}if(f.id==='stockForm'){try{await api('adjustStock',{id:fd.id,operation:fd.operation,qty:Number(fd.qty||0),reason:fd.reason||''});close();toast('Estoque atualizado e movimentação registrada.','success');sync(true)}catch(x){toast(x.message,'error')}return}});
render();setInterval(()=>{if(view.unlocked)sync(true)},45000);
})();
window.addEventListener('julih-toast',e=>toast(e.detail||'Informação'));
